function validateImportedMatch(data){
  if(!data||!data.match_metadata||data.match_metadata.synthetic!==true||!Array.isArray(data.events)||!data.events.length||data.events.length>40)return false;
  const roster=new Map([...players.values()].map(player=>[player.name,player]));
  const types=new Set(["pressure","possession","pass","reception","sprint","tackle","shot","save"]);
  const numeric=(value,min,max)=>value===undefined||(typeof value==="number"&&Number.isFinite(value)&&value>=min&&value<=max);
  const point=value=>value===undefined||(value&&typeof value==="object"&&numeric(value.x,0,110.25)&&numeric(value.y,0,46.24));
  let previous=-1,ids=new Set();
  for(const event of data.events){
    if(!event||event.synthetic!==true||typeof event.id!=="string"||!event.id.trim()||event.id.length>80||ids.has(event.id)||!types.has(event.type)||typeof event.timestamp!=="string"||!/^\d{2}:\d{2}$/.test(event.timestamp)||Number(event.timestamp.slice(3))>59)return false;
    ids.add(event.id);
    const seconds=Number(event.timestamp.slice(0,2))*60+Number(event.timestamp.slice(3));
    if(seconds<previous)return false;
    previous=seconds;
    const actor=roster.get(event.player);
    if(!actor||actor.team!==event.team)return false;
    if(event.receiver&&(!roster.has(event.receiver)||roster.get(event.receiver).team!==event.team))return false;
    if(event.detail!==undefined&&(typeof event.detail!=="string"||event.detail.length>300))return false;
    if(!point(event.from_meters)||!point(event.to_meters)||!point(event.position_m))return false;
    if(!numeric(event.distance_m,0,120)||!numeric(event.travel_seconds,0.001,3600)||!numeric(event.pressure_pct,0,100)||!numeric(event.speed_kmh,0,150))return false;
    if(event.outcome!==undefined&&(typeof event.outcome!=="string"||event.outcome.length>40))return false;
    if(event.on_target!==undefined&&typeof event.on_target!=="boolean")return false;
    if(event.type==="pass"&&(!point(event.from_meters)||!point(event.to_meters)||!Number.isFinite(event.distance_m)||!Number.isFinite(event.travel_seconds)))return false;
    if(event.type==="sprint"&&(!Number.isFinite(event.speed_kmh)||!point(event.from_meters)||!point(event.to_meters)))return false;
    if(event.type==="shot"&&(!Number.isFinite(event.speed_kmh)||!point(event.from_meters)||!point(event.to_meters)))return false;
  }
  return true;
}
