function renderStory(){let s=stats(),live=currentEvents(),p=players.get(profile.player),involved=p&&live.some(e=>e.player===p.name||e.receiver===p.name),lead=s.leadPass,receiver=lead?.receiver||live.find(e=>e.type==="reception")?.player,runner=s.runner,shot=s.shot,team=lead?.team||runner?.team||"Vale United",opponent=team==="Vale United"?"Northbridge":"Vale United",story;if(!live.length)story=T("controlWaiting");else if(mode==="analyst"){story=lang==="es"?team+": "+s.completed.length+"/"+s.passes.length+" pases completados, "+s.progression+" m de recorrido"+(runner?"; "+runner.player+" alcanzó "+runner.speed_kmh+" km/h":"")+(shot?"; remate a "+s.shotSpeed+" km/h":"; la secuencia continúa")+".":team+": "+s.completed.length+"/"+s.passes.length+" passes completed, "+s.progression+" m of progression"+(runner?"; "+runner.player+" reached "+runner.speed_kmh+" km/h":"")+(shot?"; shot at "+s.shotSpeed+" km/h":"; sequence is unfolding")+"."}else if(!lead){story=lang==="es"?opponent+" presiona la salida. Espera cómo responde "+team+".":opponent+" presses the build-up. Watch how "+team+" responds."}else if(!shot){story=lang==="es"?lead.player+" encontró a "+(receiver||"una compañera")+" con un pase de "+Math.round(lead.distance_m)+" m"+(runner?"; "+runner.player+" aceleró a "+runner.speed_kmh+" km/h":"")+". La secuencia sigue abierta.":lead.player+" found "+(receiver||"a teammate")+" with a "+Math.round(lead.distance_m)+" m pass"+(runner?"; "+runner.player+" accelerated to "+runner.speed_kmh+" km/h":"")+". The sequence is still open."}else{story=lang==="es"?shot.player+" terminó la secuencia con un tiro de "+s.shotSpeed+" km/h"+(involved?"; "+p.name+" participó en la jugada":"")+".":shot.player+" ended the sequence with a "+s.shotSpeed+" km/h shot"+(involved?"; "+p.name+" was involved":"")+"."}let why=localWhy(s,live);$(".insight-text").textContent=aiNarration?aiNarration+" "+aiWhy:story+(live.length?" "+why:"");let favTeam=profile.team==="neutral"?T("neutral"):profile.team,focus=profile.metric==="none"?"":" · "+T("metricFocus")+": "+T(profile.metric==="distance"?"metricDistanceOpt":profile.metric==="speed"?"metricSpeedOpt":"metricPressureOpt");$("[data-i18n='personalized']").textContent=(mode==="fan"?T("fan"):T("analyst"))+" · "+favTeam+(p?" · "+p.name:"")+" · "+lang.toUpperCase()+focus;$$(".metrics-row article").forEach((card,i)=>card.classList.toggle("metric-highlight",(profile.metric==="distance"&&i===0)||(profile.metric==="speed"&&i===3)||(profile.metric==="pressure"&&i===2)))}
function renderRecap(){let s=stats(),live=currentEvents(),saved=live.find(e=>e.type==="save"),first=s.leadPass,runner=s.runner,shot=s.shot,text;if(!live.length)text=lang==="es"?"La simulación espera eventos para construir el resumen.":"The simulation is waiting for events before creating a recap.";else if(!first)text=lang==="es"?live.length+" eventos sintéticos recibidos. La presión está en curso y aún no se registra un pase.":live.length+" synthetic events received. Pressure is building; no pass has been recorded yet.";else if(lang==="es")text=first.team+" salió de la presión con un pase de "+Math.round(first.distance_m)+" m hacia "+(first.receiver||"una compañera")+". "+(runner?runner.player+" aceleró a "+runner.speed_kmh+" km/h. ":"")+(shot?shot.player+" remató a "+shot.speed_kmh+" km/h"+(saved?"; "+saved.player+" atajó el balón":"")+".":"La secuencia todavía no registra un remate.")+" Se recibieron "+live.length+" eventos sintéticos; el resumen solo describe lo observado.";else text=first.team+" escaped pressure with a "+Math.round(first.distance_m)+" m pass to "+(first.receiver||"a teammate")+". "+(runner?runner.player+" accelerated to "+runner.speed_kmh+" km/h. ":"")+(shot?shot.player+" shot at "+shot.speed_kmh+" km/h"+(saved?"; "+saved.player+" made the save":"")+".":"No shot has been recorded yet.")+" "+live.length+" synthetic events were received; this recap only describes observed events."; $("[data-i18n='recapText']").textContent=aiRecap||text}
function renderSessionRecap(){let m=sessionStats(),node=$("#sessionRecapText");if(!node)return;let text;if(!m.event_count)text=lang==="es"?"Inicia el flujo sintético para acumular eventos de la sesión.":"Start the synthetic feed to collect session events.";else if(lang==="es")text=`Sesión sintética: ${m.event_count} eventos en ${m.sequence_count} secuencia(s). ${m.completed_passes}/${m.pass_count} pases completados (${m.pass_distance_m} m acumulados), ${m.shots} remate${m.shots===1?"":"s"} y ${m.saves} atajada${m.saves===1?"":"s"}.${m.peak_pressure_pct===null?"":" Presión máxima registrada: "+m.peak_pressure_pct+"%."}${m.peak_player_speed_kmh===null?"":" Velocidad máxima de carrera: "+m.peak_player_speed_kmh+" km/h."}`;else text=`Synthetic session: ${m.event_count} events across ${m.sequence_count} sequence(s). ${m.completed_passes}/${m.pass_count} completed passes (${m.pass_distance_m} m total), ${m.shots} shot${m.shots===1?"":"s"} and ${m.saves} save${m.saves===1?"":"s"}.${m.peak_pressure_pct===null?"":" Peak recorded pressure: "+m.peak_pressure_pct+"%."}${m.peak_player_speed_kmh===null?"":" Top recorded sprint speed: "+m.peak_player_speed_kmh+" km/h."}`;node.textContent=matchRecapAI||text;$("#sessionEvidence").textContent=matchRecapEvidence.length?(lang==="es"?"Referencias verificadas contra eventos recibidos: ":"References verified against received events: ")+matchRecapEvidence.join(", "):m.event_count?(lang==="es"?"Resumen calculado de los eventos recibidos; aún sin recap de IA.":"Summary calculated from received events; no AI recap yet."):"";$("#generateSessionRecap").disabled=sessionRecapLoading||!aiConfigured||!matchEvents.length||matchEvents.length>40;$("#resetSession").disabled=!matchEvents.length;$("#sessionRecapStatus").textContent=matchEvents.length>40?T("recapLimit"):matchRecapEvidence.length?(lang==="es"?"Referencias verificadas":"References verified"):aiConfigured?(lang==="es"?"Foundry listo":"Foundry ready"):(lang==="es"?"Recap local disponible":"Local recap available");$("#generateSessionRecap").textContent=matchRecapAI?(lang==="es"?"Regenerar recap de esta sesión":"Regenerate this session recap"):(lang==="es"?"Generar recap con Microsoft Foundry":"Generate recap with Microsoft Foundry")}
function renderBroadcast(live=matchEvents){let cues=overlayCues(live),list=$("#broadcastCueList");if(!list)return;list.replaceChildren();let latest=cues.slice(-5).reverse();for(const cue of latest){let row=document.createElement("article");row.className="broadcast-cue";row.innerHTML=`<span class="broadcast-cue-time"></span><div><strong></strong><p></p></div><small></small>`;row.querySelector(".broadcast-cue-time").textContent=cue.start_time;row.querySelector("strong").textContent=cue.title;row.querySelector("p").textContent=cue.text;row.querySelector("small").textContent=cue.priority.toUpperCase()+" · "+cue.event_ids.join(", ");list.append(row)}$("#broadcastStatus").textContent=lang==="es"?`${cues.length} señal(es) listas · ${live.length} evento(s) recibidos`:`${cues.length} cue(s) ready · ${live.length} event(s) received`;$("#downloadBroadcast").disabled=!cues.length}
async function requestSessionRecap(){if(!aiConfigured||!matchEvents.length||matchEvents.length>40||sessionRecapLoading)return;let button=$("#generateSessionRecap"),label=button.textContent;sessionRecapLoading=true;button.disabled=true;button.textContent=lang==="es"?"Generando…":"Generating…";$("#sessionRecapStatus").textContent=lang==="es"?"Consultando Microsoft Foundry…":"Requesting Microsoft Foundry…";try{let response=await fetch("/api/narrate",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({match_id:"synthetic-session-"+String(sessionId).padStart(3,"0"),task:"match_recap",events:matchEvents,metrics:sessionStats(),language:lang,mode,preference:{team:profile.team,player:players.get(profile.player)?.name||"",metric:profile.metric}})}),result=await response.json();if(!response.ok)throw new Error(result.error||"recap_failed");matchRecapAI=result.recap;matchRecapEvidence=result.evidence_event_ids||[];renderSessionRecap()}catch{$("#sessionRecapStatus").textContent=lang==="es"?"Foundry no pudo generar el recap. El resumen local sigue disponible.":"Foundry could not generate the recap. The local summary is still available."}finally{sessionRecapLoading=false;button.disabled=!aiConfigured||!matchEvents.length||matchEvents.length>40;button.textContent=matchRecapAI?T("regenerateAIRecap"):T("generateAIRecap")}}
