function updatePlayersAt(sec){for(const team of TEAMS)for(const row of team.players){let person=players.get(team.id+row[0]),route=[{sec:0,x:row[4],y:row[5]}];blueprint.forEach(b=>{let point=null,time=b.sec;if(b.player===person.id)point=b.type==="sprint"?b.to:(b.point||b.from||b.to);if(point)route.push({sec:time,x:point[0],y:point[1]});if(b.receiver===person.id&&b.to)route.push({sec:b.sec+(b.travel||1),x:b.to[0],y:b.to[1]})});route.sort((a,b)=>a.sec-b.sec);let prev=route[0],next=route[route.length-1];for(let i=0;i<route.length;i++){if(route[i].sec<=sec)prev=route[i];if(route[i].sec>=sec){next=route[i];break}}let ratio=next.sec===prev.sec?1:Math.max(0,Math.min(1,(sec-prev.sec)/(next.sec-prev.sec))),x=prev.x+(next.x-prev.x)*ratio,y=prev.y+(next.y-prev.y)*ratio,node=$('.player[data-player="'+person.id+'"]');if(node){node.style.setProperty('--x',x+'%');node.style.setProperty('--y',y+'%')}}}
function updatePitch(value){progress=Math.max(0,Math.min(100,Number(value)));let sec=sequenceSeconds*progress/100;updatePlayersAt(sec);let active=0;for(let i=0;i<blueprint.length;i++)if(blueprint[i].sec<=sec)active=i;let route=[];for(let b of blueprint){if(b.from)route.push({sec:b.sec,point:b.from});if(b.to)route.push({sec:b.sec+(b.travel||.15),point:b.to});else if(b.point)route.push({sec:b.sec,point:b.point})}route.sort((a,b)=>a.sec-b.sec);if(!route.length)route=[{sec:0,point:[50,50]}];let left=route[0],right=route[route.length-1];for(let i=0;i<route.length;i++){if(route[i].sec<=sec)left=route[i];if(route[i].sec>=sec){right=route[i];break}}let frac=right.sec===left.sec?1:(sec-left.sec)/(right.sec-left.sec),x=left.point[0]+(right.point[0]-left.point[0])*frac,y=left.point[1]+(right.point[1]-left.point[1])*frac;$("#ball").style.setProperty("--x",x+"%");$("#ball").style.setProperty("--y",y+"%");$("#timeline").value=progress;$("#timeline").style.background="linear-gradient(90deg,var(--lime) "+progress+"%,#2a3a4b "+progress+"%)";$("#matchMinute").innerHTML=timestamp(Math.round(sec))+" <b>"+(lang==="es"?"2.º T":"2ND H")+"</b>";$$('.player').forEach(n=>n.classList.remove('move-highlight','pressing'));let activeList=currentEvents(),event=activeList[active];if(event){let actor=[...players.values()].find(p=>p.name===event.player);if(actor){let node=$('.player[data-player="'+actor.id+'"]');if(node)node.classList.add(event.type==='pressure'?'pressing':'move-highlight')}}$$(".event-chip").forEach((n,i)=>n.classList.toggle("active-event",i===active));$("#eventCount").textContent=String(Math.min(active+1,activeList.length)).padStart(2,"0")+"/"+activeList.length;$("#metricSpeed").textContent=progress>8?stats().ballSpeed+" km/h":"—"}
function chooseAnswer(button){let correct=button.dataset.answer==="correct";$$(".answer-option").forEach(b=>{b.disabled=true;b.classList.toggle("selected",b===button);b.classList.toggle("revealed-correct",b.dataset.answer==="correct")});let v=$("#verdict");v.classList.toggle("is-correct",correct);v.classList.toggle("is-wrong",!correct);v.querySelector(".verdict-icon").textContent=correct?"✓":"↗";v.querySelector("strong").textContent=correct?(lang==="es"?"¡Correcto!":"Correct!"):(lang==="es"?"Vuelve a leer la jugada":"Read the play again");v.querySelector("p").textContent=T(correct?"correctAnswer":"wrongAnswer");$("#pitch").classList.add("show-path");updatePitch(100)}
