function setLanguage(next){lang=next;document.documentElement.lang=lang;$$("[data-i18n]").forEach(n=>{let value=T(n.dataset.i18n);if(typeof value==="string")n.textContent=value});$("#languageButton").innerHTML=lang.toUpperCase()+" <span>⌄</span>";$("#languageButton").setAttribute("aria-label",lang==="es"?"Cambiar idioma":"Change language");$("#playButton").setAttribute("aria-label",timer?T("pause"):T("play"));renderChallenge();$(".pitch-callout span:nth-child(2)").textContent=T("space");renderEvents();renderEvidence();renderFocus();renderStory();renderRecap();renderMatchState();updateScenario();resetAnswer();renderAIEvidence();renderPayload();updateAIStatus(aiNarration?"narrated":aiEnabled?"enabled":aiConfigured?"ready":"unavailable");refreshAIIfEnabled();$("#streamStatus").textContent=T(streaming?(streamTimer?"streamLive":"streamPaused"):feedCompleted?"streamDone":"streamIdle");$("#streamButton").textContent=T(streaming?(streamTimer?"pauseStream":"resumeStream"):feedCompleted?"resetStream":"startStream");$(".pitch-panel h2").textContent=importedFeed?T("livePlay"):T("scenarioNames")[activeScenarioIndex]}
function setFocus(id){profile.player=id;$("#playerPreference").value=id;renderFocus();renderStory();refreshAIIfEnabled();showToast(T("selectedPlayer")+": "+players.get(id).name)}
function saveProfile(){profile.team=$("#teamPreference").value;profile.player=$("#playerPreference").value;profile.metric=$("#metricPreference").value;localStorage.setItem("read-the-game-profile",JSON.stringify(profile));renderFocus();renderStory();$("#preferencesDialog").close();refreshAIIfEnabled();showToast(lang==="es"?"Preferencias guardadas en este dispositivo.":"Preferences saved on this device.")}
function loadProfile(){try{let p=JSON.parse(localStorage.getItem("read-the-game-profile")||"null");if(p&&players.has(p.player)&&["Vale United","Northbridge","neutral"].includes(p.team)&&["none","distance","speed","pressure"].includes(p.metric))profile=p}catch(e){}}
function setupPreferences(){TEAMS.forEach(team=>{let group=document.createElement("optgroup");group.label=team.name;team.players.forEach(p=>{let o=document.createElement("option");o.value=team.id+p[0];o.textContent=p[1]+" · #"+p[0]+" · "+p[2];group.append(o)});$("#playerPreference").append(group)});$("#teamPreference").value=profile.team;$("#playerPreference").value=profile.player;$("#metricPreference").value=profile.metric}
function toast(message){let n=$("#toast");n.textContent=message;n.classList.add("visible");clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove("visible"),2300)}
$$(".answer-option").forEach(b=>b.addEventListener("click",()=>chooseAnswer(b)));
